async function extractParts(scene,kind){const steps=extractPartSteps(scene,kind);let start=performance.now(),next;while(!(next=steps.next()).done){if(performance.now()-start>=6){await new Promise(resolve=>setTimeout(resolve,0));start=performance.now();}}return next.value;}
